    # The maintenance sweep finds executions needing attention across organisations (approval
    # deadlines, retries) before any tenant context exists. It learns ids only.
    op.execute("""
        CREATE FUNCTION operon_workflow_executions_due(p_now timestamptz, p_limit int)
        RETURNS TABLE (id uuid, organisation_id uuid)
        LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS
        $$ SELECT e.id, e.organisation_id FROM workflow_executions e
           WHERE e.next_wake_at IS NOT NULL AND e.next_wake_at <= p_now
             AND e.status IN ('awaiting_approval', 'approved', 'executing')
           ORDER BY e.next_wake_at LIMIT p_limit $$;
        REVOKE ALL ON FUNCTION operon_workflow_executions_due(timestamptz, int) FROM PUBLIC;
        GRANT EXECUTE ON FUNCTION operon_workflow_executions_due(timestamptz, int) TO operon_app;
    """)


